import{_ as l,l as s,o as e,c as n,v as t,p as i,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"ESG 理论","description":"","frontmatter":{"title":"ESG 理论","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/esg-theory.md","filePath":"econ/esg-theory.md","lastUpdated":1789023840000}'),E={name:"econ/esg-theory.md"};function c(_,a,B,m,S,u){const o=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="esg-理论" tabindex="-1">ESG 理论 <a class="header-anchor" href="#esg-理论" aria-label="Permalink to &quot;ESG 理论&quot;">​</a></h1><div class="epigraph"><p>若一部分投资者对绿色或社会属性有偏好，资产价格可以含非金钱收益；这不等于「ESG 提高了所有人的 $\\alpha$」。</p><footer>—— 对照 Pástor, Stambaugh and Taylor 的可持续投资均衡；Oehmke and Opp 对公司激励</footer></div><p><a href="/econ/cash-holdings">上一课</a>把现金当治理与摩擦下的存量。缺口是目标函数本身：股东是否只最大化财务价值。本课钉 ESG 作为偏好与约束，家族企业下一课才讲控制权结构。不把量化栏的 ESG 因子辩论再写一遍，只给公司金融一侧的均衡语言。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Hart–Zingales：若股东在商品市场也有社会偏好，最大化利润不必是一致的目标。Pástor–Stambaugh–Taylor：绿资产被偏好持有，预期金钱回报可以更低（持有人消费了「温暖」）。若把 ESG 写成无成本的 alpha，会与「谁在出钱买偏好」矛盾。缺口是分清偏好、风险管理、与代理（经理用 ESG 掩盖绩效）。</p><p><span class="marginnote">Friedman 的股东价值是基准对照，不是本课要重判的道德。Hong and Kacperczyk 的罪股溢价是价格含义的早期证据线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两块：偏好（效用含 \\(E,S,G\\) 属性）与生产（减排成本、诉讼）。均衡：绿资本成本下降，棕资本成本上升，激励真实投资直到边际成本等于价差。约束型 ESG（排除）改变风险分担，可能提高被排除资产的预期回报。治理：披露与评级是噪声信号，评级分歧本身是识别问题（后课实证识别）。</p>',8)),(e(),i(p,null,{default:r(()=>[h(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PREF%5B%22%E6%8A%95%E8%B5%84%E8%80%85%E5%81%8F%E5%A5%BD%22%5D%20--%3E%20P%5B%22%E7%BB%BF%E6%A3%95%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20P%20--%3E%20I%5B%22%E5%85%AC%E5%8F%B8%E6%8A%95%E8%B5%84%22%5D%0A%20%20AG%5B%22%E4%BB%A3%E7%90%86%20%2F%20%E6%BC%82%E7%BB%BF%22%5D%20--%3E%20NOI%5B%22%E4%BB%B7%E6%A0%BC%E5%99%AA%E5%A3%B0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>价差是偏好强度 × 资本供给弹性。若绿技术供给很快，价差消失，金钱 alpha 也消失——这是成功，不是因子失效。漂绿使信号与真实 \\(E\\) 脱钩，价差变成营销均衡。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评估某评级商。量化课的 ESG 因子是收益侧；这里是目标与资本成本。下一课金字塔控股是另一类「谁的偏好进目标函数」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ESG 首先改变谁的偏好进入目标，其次才可能改变 alpha。</li><li>绿资本成本下降是机制，不是免费午餐。</li><li>出处：Pástor–Stambaugh–Taylor；Hart–Zingales；Hong–Kacperczyk 罪股。</li></ul>',6))])}const g=l(E,[["render",c]]);export{f as __pageData,g as default};
